  const itemName = item => item?.item || item?.name || 'Unnamed Item';
  const portraitIcon = character => `<span class="portrait-initials" aria-hidden="true">${esc(initials(preferredName(character)))}</span>`;
  const GROUP_CATEGORIES = ['Revivify Resources','Healing & Potions','Weapons & Ammunition','Armor & Wearables','Magic Items','Quest Items & Documents','Crafting & Alchemy Materials','Adventuring Supplies','Food, Rations & Organic Materials','Valuables & Miscellaneous'];
  function categorizeItem(item){const text=`${itemName(item)} ${item?.type||''} ${item?.notes||''}`.toLowerCase();if(/reviv|diamond.*300|300.*diamond/.test(text))return'Revivify Resources';if(/potion|ointment|healing|elixir/.test(text))return'Healing & Potions';if(/sword|bow|crossbow|dagger|knife|club|mace|axe|arrow|bolt|weapon|scimitar/.test(text))return'Weapons & Ammunition';if(/armor|armour|shield|cloak|clothes|wearable/.test(text))return'Armor & Wearables';if(/magic|magical|sending stone|pigment|focus|glowy|rune/.test(text))return'Magic Items';if(/letter|missive|address|drawing|page|document|seal|flag|quest/.test(text))return'Quest Items & Documents';if(/dragon (tooth|teeth|talon|scale|blood)|shard|alchemy|thermite|beeswax|herb/.test(text))return'Crafting & Alchemy Materials';if(/ration|torch|tinderbox|backpack|pouch|ear plug|supplies|kit|tool/.test(text))return'Adventuring Supplies';if(/meat|food|mushroom|shroom|organic/.test(text))return'Food, Rations & Organic Materials';return'Valuables & Miscellaneous';}
  function groupedItems(items){return GROUP_CATEGORIES.map(category=>[category,(items||[]).map((item,index)=>({item,index})).filter(row=>(row.item.category||categorizeItem(row.item))===category)]).filter(([,rows])=>rows.length);}
  function featureGroup(record,character=state.character){const source=String(record.source||'Custom');if(source==='Feat')return'Feat';if(['Race','Background','Custom','Item'].includes(source))return'Race & Background';if(E.classes(character||{}).some(row=>row.subclass&&source.toLowerCase().includes(row.subclass.toLowerCase()))||/subclass|blood curse|order of/i.test(source))return'Subclass';if(/^Class(?::|$)/i.test(source)||E.classes(character||{}).some(row=>source===row.name))return'Class';return'Race & Background';}
  function ensureNotes(character){if(!Array.isArray(character.note_campaigns)||!character.note_campaigns.length){const legacy=(character.session_notes||[]).map(note=>({id:E.uid(),title:note.title||'Session Note',body:note.body||'',created_at:note.session_date||new Date().toISOString()}));character.note_campaigns=[{id:E.uid(),name:'Main Campaign',sessions:[{id:E.uid(),name:'Session 1',date:new Date().toISOString().slice(0,10),notes:legacy.length?legacy:[{id:E.uid(),title:'New Note',body:character.general_notes||'',created_at:new Date().toISOString()}]}]}];}return character.note_campaigns;}
  function ensureCombat(character){character.combat_state||={active:false,round:0,turn:0,track_enemies:false,initiative:null,action_used:false,bonus_used:false,reaction_used:false,enemies:[],pending_zero:[]};const combat=character.combat_state;combat.enemies||=[];combat.pending_zero||=[];combat.my_turn??=false;combat.session_name||='';character.combat_log||=[];character.combat_history||=[];return combat;}
  function combatActor(kind,actor){if(actor)return actor;if(kind==='enemy')return'enemy';if(['action','attack','damage','healing','reaction','magic','effect','survival','death-save','save'].includes(kind))return'player';return'system';}
  function addCombatLog(message,kind='event',actor=''){const combat=ensureCombat(state.character);state.character.combat_log.push({id:E.uid(),session_id:combat.session_id||'',round:combat.round||0,turn:combat.turn||0,kind,actor:combatActor(kind,actor),message,created_at:new Date().toISOString()});state.character.combat_log=state.character.combat_log.slice(-300);}
  function archiveCombat(){const combat=ensureCombat(state.character),logs=state.character.combat_log||[];if(!combat.session_id||!logs.length)return;const item={id:combat.session_id,name:combat.session_name||`Combat ${(state.character.combat_history||[]).length+1}`,started_at:combat.started_at||logs[0]?.created_at,ended_at:new Date().toISOString(),logs:clone(logs)};state.character.combat_history=[item,...(state.character.combat_history||[]).filter(row=>row.id!==item.id)].slice(0,100);}
  const empty = (heading='Nothing here yet',copy='This section is ready for data.') => `<div class="empty"><div><strong>${esc(heading)}</strong><span>${esc(copy)}</span></div></div>`;
  const field = (label,name,value='',type='text',extra='') => `<label>${esc(label)}<input name="${esc(name)}" type="${type}" value="${esc(value)}" ${extra}></label>`;
  const button = (label,action,id='',kind='') => `<button class="button ${kind}" type="button" data-action="${esc(action)}" ${id ? `data-id="${esc(id)}"` : ''}>${esc(label)}</button>`;
  const apiToken = (result,camel,snake) => String(result?.[camel] || result?.[snake] || '').trim();
  function validShareToken(value){return value && value !== 'undefined' && value !== 'null' && /^[a-z0-9_-]{16,}$/i.test(value);}
  function shareUrl(value){if(!validShareToken(value))throw new Error('The server did not return a valid public-session link. No session link was created.');const url=new URL(location.href);url.search='';url.hash='';url.searchParams.set('share',value);return url.href;}
  let toastTimer;
