  function setViewerExpanded(expanded){const viewer=document.querySelector('.sheet-preview');if(!viewer)return;state.viewerExpanded=Boolean(expanded);if(state.viewerExpanded&&!state.viewerHome){state.viewerHome={parent:viewer.parentNode,next:viewer.nextSibling};document.body.append(viewer);}viewer.classList.toggle('viewer-expanded',state.viewerExpanded);document.body.classList.toggle('sheet-fullscreen',state.viewerExpanded);const control=viewer.querySelector('.sheet-toolbar [data-action="maximize-sheet"],.sheet-toolbar [data-action="minimize-sheet"]');if(control){control.dataset.action=state.viewerExpanded?'minimize-sheet':'maximize-sheet';control.textContent=state.viewerExpanded?'Minimize':'Maximize';}if(!state.viewerExpanded&&state.viewerHome){const {parent,next}=state.viewerHome;parent.insertBefore(viewer,next?.parentNode===parent?next:null);state.viewerHome=null;}}
  function setSheetZoom(value){const viewport=document.querySelector('.paper-viewport'),stack=document.querySelector('.paper-stack');if(!stack)return;if(value==='fit'){const page=stack.querySelector('.paper-page');state.viewerZoom=page&&viewport?Math.max(.4,Math.min(1.6,(viewport.clientWidth-32)/page.offsetWidth)):1;}else state.viewerZoom=Math.max(.4,Math.min(1.6,Number(value)||1));stack.style.setProperty('--sheet-zoom',state.viewerZoom);const range=document.querySelector('[data-sheet-zoom]'),output=document.querySelector('[data-zoom-output]');if(range)range.value=Math.round(state.viewerZoom*100);if(output)output.textContent=`${Math.round(state.viewerZoom*100)}%`;}
